const DEDUPE_TTL_SECONDS = 43_200;

export async function claimDelivery(deliveryId: string): Promise<boolean> {
  const created = await redis.set(`webhook:${deliveryId}`, '1', { NX: true, EX: DEDUPE_TTL_SECONDS });
  return created === 'OK';
}

export async function handleWebhook(delivery: Delivery) {
  if (!(await claimDelivery(delivery.id))) return;
  await applyDeliverySideEffects(delivery);
}

